<?php
/**
 * Nahian POS Menu Category Delete Handler
 *
 * @package NRTOK_POS
 * @since   1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( isset( $_GET['del_cat'] ) ) {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have sufficient permissions to perform this action.', 'nahian-restaurant-ordering-system' ) );
	}

	$cat_id = absint( $_GET['del_cat'] );
	if ( $cat_id > 0 ) {
		// Verify CSRF nonce generated by wp_nonce_url() in category-list.php & category-view.php.
		check_admin_referer( 'nrtok_delete_cat_' . $cat_id );

		global $wpdb;
		$t_cats    = $wpdb->prefix . 'nrtok_categories';
		$t_menu    = $wpdb->prefix . 'nrtok_menu';
		$svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

		// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
		if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_cats ) ) === $t_cats ) {
			// First, fetch category name so we can unassign or move dishes belonging to it.
			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
			$cat_row = $wpdb->get_row( $wpdb->prepare( 'SELECT name FROM %i WHERE id = %d', $t_cats, $cat_id ) );

			// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
			$deleted = $wpdb->delete(
				$t_cats,
				array( 'id' => $cat_id ),
				array( '%d' )
			);

			if ( false !== $deleted && $deleted > 0 ) {
				// If category was deleted, unassign any dishes belonging to it (set category to 'Uncategorized' or empty).
				if ( $cat_row && ! empty( $cat_row->name ) ) {
					// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
					if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $t_menu ) ) === $t_menu ) {
						// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
						$wpdb->update(
							$t_menu,
							array( 'category' => __( 'Uncategorized', 'nahian-restaurant-ordering-system' ) ),
							array( 'category' => $cat_row->name ),
							array( '%s' ),
							array( '%s' )
						);
					}
				}

				echo '<div class="nrtok-alert nrtok-cat-alert-flex">' . $svg_check . '<span>' . sprintf( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
					/* translators: %d: category ID */
					esc_html__( 'Category #%d deleted successfully!', 'nahian-restaurant-ordering-system' ),
					absint( $cat_id )
				) . '</span></div>';
			} else {
				echo '<div class="nrtok-alert" style="background:#fef2f2; border-color:#fecaca; color:#b91c1c;">' . esc_html__( 'Category could not be deleted or was already removed.', 'nahian-restaurant-ordering-system' ) . '</div>';
			}
		}
	}
}